export const emcFlybackControl =
  '* EMC_flyback_control.lib\n* Behavioural models for the control loop of the EMC demo flyback (rev B board):\n*   UC3845B  current-mode PWM controller   (U1)\n*   TL431B   shunt reference / error amp   (U3)\n*   LTV817   optocoupler                   (U4)\n* Only B-sources, F-sources, R, C and D are used, so the same file runs in LTspice and ngspice.\n* Global parameters used (define them on the schematic): CTR, FOPTO, RDIV\n*\n* ======================================================================= UC3845B\n* Pin order = datasheet pins 1..8: COMP FB ISENSE RTCT GND OUT VCC VREF\n* What is modelled:\n*  - 5 V reference, UVLO (on above 8.4 V)\n*  - oscillator: RT/CT charged from VREF via RT, discharged with 8.3 mA between 2.8 V (peak) and 1.2 V (valley)\n*  - toggle flip-flop (UC3845 = half the oscillator frequency, max. duty < 50 %)\n*  - PWM latch: set by the oscillator, reset when V(ISENSE) > (V(COMP)-1.4 V)/3, clamped at 1.0 V\n*  - ~70 ns current-sense-to-output delay, totem-pole output VOH = VCC-1.5 V, 4 ohm, ~15 ns edges\n*  - error amplifier: with FB grounded the COMP pin is pulled high by a 0.8 mA source (datasheet typ.),\n*    VOH 5.5 V; it can sink up to 6 mA. The internal 2R/R divider that feeds the current-sense comparator\n*    loads COMP with (V(COMP)-1.4 V)/RDIV (RDIV is not given in the datasheet: an assumption, default 30k)\n.subckt UC3845B COMP FB ISENSE RTCT GN OUT VCC VREF\n* reference + UVLO\nBon en GN V=u(V(VCC,GN)-8.4)\nBref vr GN V=5*V(en,GN)\nRref vr VREF 2\n* oscillator latch d = 1 while discharging\nBd dd GN V=u(V(RTCT,GN)-2.8) + u(V(RTCT,GN)-1.2)*(1-u(V(RTCT,GN)-2.8))*u(V(d,GN)-0.5)\nRd dd d 1k\nCd d GN 1p\nBdis RTCT GN I=8.3m*u(V(d,GN)-0.5)\n* toggle flip-flop (master m, slave q), clocked by d\nBm mm GN V=u(V(d,GN)-0.5)*(1-u(V(q,GN)-0.5)) + (1-u(V(d,GN)-0.5))*u(V(m,GN)-0.5)\nRm mm m 1k\nCm m GN 1p\nBq qq GN V=u(V(d,GN)-0.5)*u(V(q,GN)-0.5) + (1-u(V(d,GN)-0.5))*u(V(m,GN)-0.5)\nRq qq q 1k\nCq q GN 1p\n* error amplifier (inverting input FB, internal 2.5 V reference), current-limited output\nBtg tg GN V=min(5.5, max(0.1, 2.5 + 1e4*(2.5-V(FB,GN))))\nBea GN COMP I=min(0.8m, max(-6m, (V(tg,GN)-V(COMP,GN))/100))\nBdiv COMP GN I=max(0, V(COMP,GN)-1.4)/{RDIV}\nRfb FB GN 100Meg\nRcp COMP GN 10Meg\n* current-sense comparator (threshold (Vcomp-1.4)/3, 1 V clamp) with ~70 ns delay\nBth th GN V=min(1, max(0, (V(COMP,GN)-1.4)/3))\nBcmp cc GN V=u(V(ISENSE,GN)-V(th,GN))\nRc cc c 1k\nCc c GN 100p\nRis ISENSE GN 10Meg\n* PWM latch: set while the oscillator discharges, reset by the comparator\nBl ll GN V=u(V(d,GN)-0.5) + (1-u(V(d,GN)-0.5))*(1-u(V(c,GN)-0.5))*u(V(l,GN)-0.5)\nRl ll l 1k\nCl l GN 1p\n* output stage (blanked during discharge, enabled after 1 us so the DC operating point starts with Q1 off)\nBo oo GN V=(V(VCC,GN)-1.5)*(1-u(V(d,GN)-0.5))*u(V(l,GN)-0.5)*u(V(q,GN)-0.5)*V(en,GN)*u(time-1u)\nRo oo o 1k\nCo o GN 15p\nBdrv od GN V=V(o,GN)\nRout od OUT 4\n.ends UC3845B\n*\n* ======================================================================= TL431B\n* Pins: K A REF. Vref = 2.495 V, open-loop gain 60 dB with a 1.5 kHz pole, cathode current >= 0,\n* needs V(K,A) > ~1.5 V, 0.3 mA quiescent current.\n.subckt TL431B K A REF\nBx xe A V=min(30, max(-1, 1000*(V(REF,A)-2.495)))\nRx xe x 1k\nCx x A 106n\nBk K A I=(1m*max(V(x,A),0)+0.3m)*(1-exp(-max(V(K,A)-1.0,0)/0.3))\nRr REF A 50Meg\n.ends TL431B\n*\n* ======================================================================= LTV817\n* Pins: A K C E. LED (Vf ~1.1 V at 1 mA) -> collector current = CTR * I_LED with a single pole FOPTO,\n* soft saturation below ~0.3 V V(C,E).\n.subckt LTV817 A K C E\nVs A a1 0\nD1 a1 K LEDIR\nF1 E fi Vs 1\nRfi fi E 1k\nCfi fi E {1/(6.2832*1k*FOPTO)}\nBc C E I={CTR}*V(fi,E)/1k*(1-exp(-max(V(C,E),0)/0.15))\nCce C E 10p\n.model LEDIR D(Is=1.5e-13 N=1.8 Rs=2 Cjo=30p)\n.ends LTV817\n';
